  1→/**
  2→ * Type-safe API client for integration tests
  3→ *
  4→ * Provides convenient methods for making API requests
  5→ * with proper error handling and response parsing.
  6→ */
  7→
  8→import { collectSSEEvents, type SSEEvent } from './sse-parser';
  9→
 10→export interface ApiResponse<T = unknown> {
 11→  ok: boolean;
 12→  status: number;
 13→  data: T;
 14→  headers: Headers;
 15→}
 16→
 17→export interface ApiErrorResponse {
 18→  ok: false;
 19→  status: number;
 20→  error: string;
 21→  headers: Headers;
 22→}
 23→
 24→export type ApiResult<T> = ApiResponse<T> | ApiErrorResponse;
 25→
 26→/**
 27→ * Create an API client with a base URL and optional custom fetch
 28→ */
 29→export function createApiClient(baseUrl: string, customFetch: typeof fetch = fetch) {
 30→  const normalizedBaseUrl = baseUrl.replace(/\/$/, '');
 31→
 32→  async function request<T = unknown>(
 33→    method: string,
 34→    path: string,
 35→    options: {
 36→      body?: unknown;
 37→      headers?: Record<string, string>;
 38→      query?: Record<string, string | number | boolean | undefined>;
 39→    } = {}
 40→  ): Promise<ApiResult<T>> {
 41→    const { body, headers = {}, query } = options;
 42→
 43→    let url = `${normalizedBaseUrl}${path}`;
 44→
 45→    // Add query parameters
 46→    if (query) {
 47→      const params = new URLSearchParams();
 48→      for (const [key, value] of Object.entries(query)) {
 49→        if (value !== undefined) {
 50→          params.set(key, String(value));
 51→        }
 52→      }
 53→      const queryString = params.toString();
 54→      if (queryString) {
 55→        url += `?${queryString}`;
 56→      }
 57→    }
 58→
 59→    const requestHeaders: Record<string, string> = {
 60→      ...headers,
 61→    };
 62→
 63→    if (body !== undefined) {
 64→      requestHeaders['Content-Type'] = 'application/json';
 65→    }
 66→
 67→    const response = await customFetch(url, {
 68→      method,
 69→      headers: requestHeaders,
 70→      body: body !== undefined ? JSON.stringify(body) : undefined,
 71→    });
 72→
 73→    if (!response.ok) {
 74→      let errorMessage = `HTTP ${response.status}`;
 75→      try {
 76→        const errorData = await response.json();
 77→        errorMessage = errorData.error || errorData.message || errorMessage;
 78→      } catch {
 79→        // Use default error message
 80→      }
 81→
 82→      return {
 83→        ok: false,
 84→        status: response.status,
 85→        error: errorMessage,
 86→        headers: response.headers,
 87→      };
 88→    }
 89→
 90→    let data: T;
 91→    const contentType = response.headers.get('content-type');
 92→
 93→    if (contentType?.includes('application/json')) {
 94→      data = await response.json();
 95→    } else {
 96→      data = (await response.text()) as unknown as T;
 97→    }
 98→
 99→    return {
100→      ok: true,
101→      status: response.status,
102→      data,
103→      headers: response.headers,
104→    };
105→  }
106→
107→  return {
108→    /**
109→     * Make a GET request
110→     */
111→    get<T = unknown>(
112→      path: string,
113→      options?: {
114→        headers?: Record<string, string>;
115→        query?: Record<string, string | number | boolean | undefined>;
116→      }
117→    ): Promise<ApiResult<T>> {
118→      return request<T>('GET', path, options);
119→    },
120→
121→    /**
122→     * Make a POST request
123→     */
124→    post<T = unknown>(
125→      path: string,
126→      body?: unknown,
127→      options?: {
128→        headers?: Record<string, string>;
129→        query?: Record<string, string | number | boolean | undefined>;
130→      }
131→    ): Promise<ApiResult<T>> {
132→      return request<T>('POST', path, { ...options, body });
133→    },
134→
135→    /**
136→     * Make a PATCH request
137→     */
138→    patch<T = unknown>(
139→      path: string,
140→      body?: unknown,
141→      options?: {
142→        headers?: Record<string, string>;
143→        query?: Record<string, string | number | boolean | undefined>;
144→      }
145→    ): Promise<ApiResult<T>> {
146→      return request<T>('PATCH', path, { ...options, body });
147→    },
148→
149→    /**
150→     * Make a PUT request
151→     */
152→    put<T = unknown>(
153→      path: string,
154→      body?: unknown,
155→      options?: {
156→        headers?: Record<string, string>;
157→        query?: Record<string, string | number | boolean | undefined>;
158→      }
159→    ): Promise<ApiResult<T>> {
160→      return request<T>('PUT', path, { ...options, body });
161→    },
162→
163→    /**
164→     * Make a DELETE request
165→     */
166→    delete<T = unknown>(
167→      path: string,
168→      options?: {
169→        headers?: Record<string, string>;
170→        query?: Record<string, string | number | boolean | undefined>;
171→      }
172→    ): Promise<ApiResult<T>> {
173→      return request<T>('DELETE', path, options);
174→    },
175→
176→    /**
177→     * Make a request to an SSE endpoint and collect events
178→     */
179→    async sse(
180→      path: string,
181→      body?: unknown,
182→      options?: {
183→        headers?: Record<string, string>;
184→        timeout?: number;
185→        maxEvents?: number;
186→      }
187→    ): Promise<{ ok: boolean; status: number; events: SSEEvent[] }> {
188→      const { headers = {}, timeout, maxEvents } = options || {};
189→
190→      const url = `${normalizedBaseUrl}${path}`;
191→      const requestHeaders: Record<string, string> = {
192→        ...headers,
193→      };
194→
195→      if (body !== undefined) {
196→        requestHeaders['Content-Type'] = 'application/json';
197→      }
198→
199→      const response = await customFetch(url, {
200→        method: body !== undefined ? 'POST' : 'GET',
201→        headers: requestHeaders,
202→        body: body !== undefined ? JSON.stringify(body) : undefined,
203→      });
204→
205→      if (!response.ok) {
206→        return {
207→          ok: false,
208→          status: response.status,
209→          events: [],
210→        };
211→      }
212→
213→      const events = await collectSSEEvents(response, { timeout, maxEvents });
214→
215→      return {
216→        ok: true,
217→        status: response.status,
218→        events,
219→      };
220→    },
221→
222→    /**
223→     * Make a raw request and return the Response object
224→     */
225→    async raw(
226→      method: string,
227→      path: string,
228→      options?: {
229→        body?: unknown;
230→        headers?: Record<string, string>;
231→      }
232→    ): Promise<Response> {
233→      const { body, headers = {} } = options || {};
234→
235→      const url = `${normalizedBaseUrl}${path}`;
236→      const requestHeaders: Record<string, string> = {
237→        ...headers,
238→      };
239→
240→      if (body !== undefined) {
241→        requestHeaders['Content-Type'] = 'application/json';
242→      }
243→
244→      return customFetch(url, {
245→        method,
246→        headers: requestHeaders,
247→        body: body !== undefined ? JSON.stringify(body) : undefined,
248→      });
249→    },
250→  };
251→}
252→
253→export type ApiClient = ReturnType<typeof createApiClient>;
