  1→/**
  2→ * Type-safe API client for integration tests
  3→ *
  4→ * Provides convenient methods for making API requests
  5→ * with proper error handling and response parsing.
  6→ */
  7→
  8→import { collectSSEEvents, type SSEEvent } from './sse-parser';
  9→
 10→export interface ApiResponse<T = unknown> {
 11→  ok: boolean;
 12→  status: number;
 13→  data: T;
 14→  headers: Headers;
 15→}
 16→
 17→export interface ApiErrorResponse {
 18→  ok: false;
 19→  status: number;
 20→  error: string;
 21→  headers: Headers;
 22→}
 23→
 24→export type ApiResult<T> = ApiResponse<T> | ApiErrorResponse;
 25→
 26→/**
 27→ * Create an API client with a base URL and optional custom fetch
 28→ */
 29→export function createApiClient(baseUrl: string, customFetch: typeof fetch = fetch) {
 30→  const normalizedBaseUrl = baseUrl.replace(/\/$/, '');
 31→
 32→  async function request<T = unknown>(
 33→    method: string,
 34→    path: string,
 35→    options: {
 36→      body?: unknown;
 37→      headers?: Record<string, string>;
 38→      query?: Record<string, string | number | boolean | undefined>;
 39→    } = {}
 40→  ): Promise<ApiResult<T>> {
 41→    const { body, headers = {}, query } = options;
 42→
 43→    let url = `${normalizedBaseUrl}${path}`;
 44→
 45→    // Add query parameters
 46→    if (query) {
 47→      const params = new URLSearchParams();
 48→      for (const [key, value] of Object.entries(query)) {
 49→        if (value !== undefined) {
 50→          params.set(key, String(value));
 51→        }
 52→      }
 53→      const queryString = params.toString();
 54→      if (queryString) {
 55→        url += `?${queryString}`;
 56→      }
 57→    }
 58→
 59→    const requestHeaders: Record<string, string> = {
 60→      ...headers,
 61→    };
 62→
 63→    if (body !== undefined) {
 64→      requestHeaders['Content-Type'] = 'application/json';
 65→    }
 66→
 67→    const response = await customFetch(url, {
 68→      method,
 69→      headers: requestHeaders,
 70→      body: body !== undefined ? JSON.stringify(body) : undefined,
 71→    });
 72→
 73→    if (!response.ok) {
 74→      let errorMessage = `HTTP ${response.status}`;
 75→      try {
 76→        const errorData = await response.json();
 77→        errorMessage = errorData.error || errorData.message || errorMessage;
 78→      } catch {
 79→        // Use default error message
 80→      }
 81→
 82→      return {
 83→        ok: false,
 84→        status: response.status,
 85→        error: errorMessage,
 86→        headers: response.headers,
 87→      };
 88→    }
 89→
 90→    let data: T;
 91→    const contentType = response.headers.get('content-type');
 92→
 93→    if (contentType?.includes('application/json')) {
 94→      data = await response.json();
 95→    } else {
 96→      data = (await response.text()) as unknown as T;
 97→    }
 98→
 99→    return {
100→      ok: true,
101→      status: response.status,
102→      data,
103→      headers: response.headers,
104→    };
105→  }
106→
107→  return {
108→    /**
109→     * Make a GET request
110→     */
111→    get<T = unknown>(
112→      path: string,
113→      options?: {
114→        headers?: Record<string, string>;
115→        query?: Record<string, string | number | boolean | undefined>;
