  1→/**
  2→ * Executor Resolution Logic
  3→ *
  4→ * Handles the cascade resolution for hot-swappable executors:
  5→ * Agent Config → Collection Config → System Default
  6→ */
  7→
  8→import { executePackage } from '@tpmjs/package-executor';
  9→import type {
 10→  CreateSessionResponse,
 11→  DestroySessionResponse,
 12→  ExecuteToolRequest,
 13→  ExecuteToolResponse,
 14→  ExecutorConfig,
 15→  ExecutorHealthResponse,
 16→  SandboxExecutorConfig,
 17→} from '@tpmjs/types/executor';
 18→
 19→const DEFAULT_TIMEOUT = 300000; // 5 minutes for custom executors
 20→const MAX_RETRIES = 2;
 21→const RETRY_BASE_DELAY_MS = 1000;
 22→
 23→/**
 24→ * Retry helper with exponential backoff
 25→ */
 26→async function withRetry<T>(
 27→  fn: () => Promise<T>,
 28→  opts: { maxRetries?: number; shouldRetry?: (error: unknown) => boolean } = {}
 29→): Promise<T> {
 30→  const maxRetries = opts.maxRetries ?? MAX_RETRIES;
 31→  let lastError: unknown;
 32→
 33→  for (let attempt = 0; attempt <= maxRetries; attempt++) {
 34→    try {
 35→      return await fn();
 36→    } catch (error) {
 37→      lastError = error;
 38→      if (attempt >= maxRetries) break;
 39→      if (opts.shouldRetry && !opts.shouldRetry(error)) break;
 40→
 41→      const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
 42→      console.warn(
 43→        `[Executor] Retry ${attempt + 1}/${maxRetries} after ${delay}ms:`,
 44→        error instanceof Error ? error.message : String(error)
 45→      );
 46→      await new Promise((resolve) => setTimeout(resolve, delay));
 47→    }
 48→  }
 49→
 50→  throw lastError;
 51→}
 52→
 53→/**
 54→ * Resolve executor configuration using cascade:
 55→ * Agent Config → Collection Config → System Default
 56→ *
 57→ * @param agentConfig - Executor config from Agent (highest priority)
 58→ * @param collectionConfig - Executor config from Collection (medium priority)
 59→ * @returns Resolved executor configuration
 60→ */
 61→export function resolveExecutorConfig(
 62→  agentConfig: ExecutorConfig | null | undefined,
 63→  collectionConfig: ExecutorConfig | null | undefined
 64→): ExecutorConfig {
 65→  // Agent config takes precedence
 66→  if (agentConfig && agentConfig.type !== 'default') {
 67→    return agentConfig;
 68→  }
 69→
 70→  // Fall back to collection config
 71→  if (collectionConfig && collectionConfig.type !== 'default') {
 72→    return collectionConfig;
 73→  }
 74→
 75→  // System default
 76→  return { type: 'default' };
 77→}
 78→
 79→/**
 80→ * Parse executor config from database JSON
 81→ * Handles null/undefined and validates the shape
 82→ */
 83→export function parseExecutorConfig(
 84→  executorType: string | null | undefined,
 85→  executorConfig: unknown
 86→): ExecutorConfig | null {
 87→  if (!executorType) {
 88→    return null;
 89→  }
 90→
 91→  if (executorType === 'default') {
 92→    return { type: 'default' };
 93→  }
 94→
 95→  if (executorType === 'custom_url' && executorConfig && typeof executorConfig === 'object') {
 96→    const config = executorConfig as { url?: string; apiKey?: string };
 97→    if (config.url && typeof config.url === 'string') {
 98→      return {
 99→        type: 'custom_url',
100→        url: config.url,
101→        apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
102→      };
103→    }
104→  }
105→
106→  if (executorType === 'sandbox') {
107→    const config =
108→      executorConfig && typeof executorConfig === 'object'
109→        ? (executorConfig as { url?: string; apiKey?: string })
110→        : {};
111→    return {
112→      type: 'sandbox',
113→      url: typeof config.url === 'string' ? config.url : undefined,
114→      apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
115→    };
116→  }
117→
118→  return null;
119→}
120→
121→/**
122→ * Execute a tool using a custom URL executor
123→ */
124→async function executeWithCustomUrl(
125→  url: string,
126→  apiKey: string | undefined,
127→  request: ExecuteToolRequest,
128→  timeout: number = DEFAULT_TIMEOUT
129→): Promise<ExecuteToolResponse> {
130→  const startTime = Date.now();
131→
132→  const headers: Record<string, string> = {
133→    'Content-Type': 'application/json',
134→  };
135→
136→  if (apiKey) {
137→    headers.Authorization = `Bearer ${apiKey}`;
138→  }
139→
140→  try {
141→    const controller = new AbortController();
142→    const timeoutId = setTimeout(() => controller.abort(), timeout);
143→
144→    const response = await fetch(`${url}/execute-tool`, {
145→      method: 'POST',
146→      headers,
147→      body: JSON.stringify(request),
148→      signal: controller.signal,
149→    });
150→
151→    clearTimeout(timeoutId);
152→
153→    const executionTimeMs = Date.now() - startTime;
154→
155→    if (!response.ok) {
156→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
157→        error?: string;
158→      };
159→      return {
160→        success: false,
161→        error: errorData.error || `Executor error: ${response.status}`,
162→        executionTimeMs,
163→      };
164→    }
165→
166→    const result = (await response.json()) as ExecuteToolResponse;
167→
168→    return {
169→      success: result.success,
170→      output: result.output,
171→      error: result.error,
172→      executionTimeMs: result.executionTimeMs || executionTimeMs,
173→    };
174→  } catch (error) {
175→    const executionTimeMs = Date.now() - startTime;
176→
177→    if (error instanceof Error && error.name === 'AbortError') {
178→      return {
179→        success: false,
180→        error: 'Execution timeout',
181→        executionTimeMs,
182→      };
183→    }
184→
185→    return {
186→      success: false,
187→      error: error instanceof Error ? error.message : String(error),
188→      executionTimeMs,
189→    };
190→  }
191→}
