400→          console.warn(
401→            `[Sandbox] Network error, retrying in ${delay}ms (attempt ${attempt + 1}):`,
402→            msg
403→          );
404→          await new Promise((resolve) => setTimeout(resolve, delay));
405→          continue;
406→        }
407→      }
408→
409→      return {
410→        success: false,
411→        error: error instanceof Error ? error.message : String(error),
412→        executionTimeMs: Date.now() - startTime,
413→      };
414→    }
415→  }
416→
417→  return {
418→    success: false,
419→    error: lastError instanceof Error ? lastError.message : String(lastError),
420→    executionTimeMs: Date.now() - startTime,
421→  };
422→}
423→
424→/**
425→ * Execute a tool using the resolved executor configuration
426→ *
427→ * @param config - Resolved executor config (or null for default)
428→ * @param request - Tool execution request
429→ * @param sessionId - Optional session ID for sandbox executors
430→ * @returns Execution result
431→ */
432→export async function executeWithExecutor(
433→  config: ExecutorConfig | null,
434→  request: ExecuteToolRequest,
435→  sessionId?: string
436→): Promise<ExecuteToolResponse> {
437→  const resolvedConfig = config ?? { type: 'default' };
438→
