472→/**
473→ * Check the health of a custom executor URL
474→ *
475→ * @param url - Executor URL to check
476→ * @param apiKey - Optional API key for authentication
477→ * @returns Health check response or error
478→ */
479→export async function checkExecutorHealth(
480→  url: string,
481→  apiKey?: string
482→): Promise<{ healthy: boolean; response?: ExecutorHealthResponse; error?: string }> {
483→  const headers: Record<string, string> = {};
484→
485→  if (apiKey) {
486→    headers.Authorization = `Bearer ${apiKey}`;
487→  }
488→
489→  try {
490→    const controller = new AbortController();
491→    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout for health checks
492→
493→    const response = await fetch(`${url}/health`, {
494→      method: 'GET',
495→      headers,
496→      signal: controller.signal,
497→    });
498→
499→    clearTimeout(timeoutId);
500→
501→    if (!response.ok) {
502→      return {
503→        healthy: false,
504→        error: `Health check failed: ${response.status}`,
505→      };
506→    }
507→
508→    const data = (await response.json()) as ExecutorHealthResponse;
509→
510→    return {
511→      healthy: data.status === 'ok' || data.status === 'degraded',
512→      response: data,
513→    };
514→  } catch (error) {
515→    if (error instanceof Error && error.name === 'AbortError') {
516→      return {
517→        healthy: false,
518→        error: 'Health check timeout',
519→      };
520→    }
521→
522→    return {
523→      healthy: false,
524→      error: error instanceof Error ? error.message : 'Unknown error',
525→    };
526→  }
527→}
