556→/**
557→ * Verify a custom executor URL is valid and operational
558→ *
559→ * @param url - Executor URL to verify
560→ * @param apiKey - Optional API key for authentication
561→ * @returns Verification result
562→ */
563→export async function verifyExecutor(
564→  url: string,
565→  apiKey?: string
566→): Promise<{
567→  valid: boolean;
568→  healthCheck?: { healthy: boolean; response?: ExecutorHealthResponse };
569→  testExecution?: { success: boolean; executionTimeMs: number };
570→  errors: string[];
571→}> {
572→  const errors: string[] = [];
573→
574→  // Validate URL format
575→  try {
576→    const parsed = new URL(url);
577→    if (parsed.protocol !== 'https:' && process.env.NODE_ENV === 'production') {
578→      errors.push('Custom executor URL must use HTTPS in production');
579→    }
580→  } catch {
581→    errors.push('Invalid URL format');
582→    return { valid: false, errors };
583→  }
584→
585→  // Check health endpoint
586→  const healthResult = await checkExecutorHealth(url, apiKey);
587→  if (!healthResult.healthy) {
588→    errors.push(healthResult.error || 'Health check failed');
589→  }
590→
591→  // Test execution (only if health check passed)
592→  let testResult: { success: boolean; executionTimeMs: number } | undefined;
593→  if (healthResult.healthy) {
594→    const execResult = await testExecutor(url, apiKey);
595→    testResult = {
596→      success: execResult.success,
597→      executionTimeMs: execResult.executionTimeMs,
598→    };
599→    if (!execResult.success) {
600→      errors.push(execResult.error || 'Test execution failed');
601→    }
602→  }
603→
604→  return {
605→    valid: errors.length === 0,
606→    healthCheck: {
607→      healthy: healthResult.healthy,
608→      response: healthResult.response,
609→    },
610→    testExecution: testResult,
611→    errors,
612→  };
613→}
