 1→/**
 2→ * Sandbox test context
 3→ *
 4→ * Provides environment detection, client configuration, session tracking,
 5→ * and cleanup for sandbox integration tests (Layer 1 — direct API).
 6→ */
 7→
 8→import { type SandboxClient, createSandboxClient } from './sandbox-client';
 9→
10→// ─── Environment ─────────────────────────────────────────────────────────────
11→
12→/** Returns true if SANDBOX_TEST_URL is set. All Layer 1 tests gate on this. */
13→export function isSandboxAvailable(): boolean {
14→  return !!process.env.SANDBOX_TEST_URL;
15→}
16→
17→/** Disk quota in MB the sandbox was started with (for quota tests). */
18→export function getSandboxDiskQuotaMB(): number {
19→  return Number(process.env.SANDBOX_TEST_DISK_QUOTA_MB || '100');
20→}
21→
22→// ─── Test Context ────────────────────────────────────────────────────────────
23→
24→export interface SandboxTestContext {
25→  /** Pre-configured sandbox HTTP client */
26→  client: SandboxClient;
27→  /** Generate a unique session ID for this test run */
28→  uniqueSessionId: (prefix?: string) => string;
29→  /** Track a session for cleanup */
30→  trackSession: (sessionId: string) => void;
31→  /** Destroy all tracked sessions */
32→  cleanup: () => Promise<void>;
33→}
34→
35→let counter = 0;
36→
37→/**
38→ * Build a fresh sandbox test context.
39→ *
40→ * Call `cleanup()` in afterAll / afterEach to destroy sessions created during tests.
41→ */
42→export function getSandboxTestContext(): SandboxTestContext {
43→  const baseUrl = process.env.SANDBOX_TEST_URL || 'http://localhost:3002';
44→  const apiKey = process.env.SANDBOX_TEST_API_KEY;
45→
46→  const client = createSandboxClient({ baseUrl, apiKey });
47→  const trackedSessions: string[] = [];
48→
49→  return {
50→    client,
51→
52→    uniqueSessionId(prefix = 'test') {
53→      counter++;
54→      return `${prefix}-${Date.now()}-${counter}`;
55→    },
56→
57→    trackSession(sessionId: string) {
58→      trackedSessions.push(sessionId);
59→    },
60→
61→    async cleanup() {
62→      const results = await Promise.allSettled(
63→        trackedSessions.map((id) => client.destroySession(id))
64→      );
65→      for (const r of results) {
66→        if (r.status === 'rejected') {
67→          console.warn('Session cleanup warning:', r.reason);
68→        }
69→      }
70→      trackedSessions.length = 0;
71→    },
72→  };
73→}
