  1→/**
  2→ * HTTP client for the sandbox server API
  3→ *
  4→ * Purpose-built for the sandbox server's Bearer token auth,
  5→ * separate from the web app's api-client.ts (which uses session cookies / API keys).
  6→ */
  7→
  8→// ─── Response Types ──────────────────────────────────────────────────────────
  9→
 10→export interface SandboxHealthResponse {
 11→  status: string;
 12→  version: string;
 13→  info: {
 14→    runtime: string;
 15→    denoVersion: string;
 16→    activeSessions: number;
 17→    maxSessions: number;
 18→    cachedModules: number;
 19→    capabilities: {
 20→      sessions: boolean;
 21→      executeToolWithSession: boolean;
 22→    };
 23→  };
 24→}
 25→
 26→export interface SandboxMetricsResponse {
 27→  uptime: number;
 28→  sessions: {
 29→    active: number;
 30→    max: number;
 31→    totalCreated: number;
 32→    totalDestroyed: number;
 33→  };
 34→  executions: {
 35→    total: number;
 36→    successful: number;
 37→    failed: number;
 38→  };
 39→  memory: {
 40→    rss: number;
 41→    heapUsed: number;
 42→    heapTotal: number;
 43→  };
 44→  cache: {
 45→    modules: number;
 46→    maxSize: number;
 47→  };
 48→}
 49→
 50→export interface SandboxSessionResponse {
 51→  sessionId: string;
 52→  workDir: string;
 53→  createdAt: string;
 54→  expiresAt: string;
 55→  resumed?: boolean;
 56→  toolCallCount?: number;
 57→}
 58→
 59→export interface SandboxExecuteResponse {
 60→  success: boolean;
 61→  output?: unknown;
 62→  error?: string;
 63→  executionTimeMs: number;
 64→}
 65→
 66→export interface SandboxErrorResponse {
 67→  error: string;
 68→}
 69→
 70→// ─── Client ──────────────────────────────────────────────────────────────────
 71→
 72→export interface SandboxClientOptions {
 73→  baseUrl: string;
 74→  apiKey?: string;
 75→}
 76→
 77→export function createSandboxClient(options: SandboxClientOptions) {
 78→  const { baseUrl, apiKey } = options;
 79→  const normalizedUrl = baseUrl.replace(/\/$/, '');
 80→
 81→  function authHeaders(): Record<string, string> {
 82→    if (!apiKey) return {};
 83→    return { Authorization: `Bearer ${apiKey}` };
 84→  }
 85→
 86→  async function parseJson<T>(response: Response): Promise<T> {
 87→    return response.json() as Promise<T>;
 88→  }
 89→
 90→  return {
 91→    /** GET /health — no auth required */
 92→    async health(): Promise<{ status: number; data: SandboxHealthResponse }> {
 93→      const res = await fetch(`${normalizedUrl}/health`);
 94→      const data = await parseJson<SandboxHealthResponse>(res);
 95→      return { status: res.status, data };
 96→    },
 97→
 98→    /** GET /metrics — no auth required */
 99→    async metrics(): Promise<{ status: number; data: SandboxMetricsResponse }> {
100→      const res = await fetch(`${normalizedUrl}/metrics`);
101→      const data = await parseJson<SandboxMetricsResponse>(res);
102→      return { status: res.status, data };
103→    },
104→
105→    /** POST /sessions — create or resume a session */
106→    async createSession(
107→      sessionId: string,
108→      timeoutSeconds?: number
109→    ): Promise<{ status: number; data: SandboxSessionResponse }> {
110→      const res = await fetch(`${normalizedUrl}/sessions`, {
111→        method: 'POST',
112→        headers: { 'Content-Type': 'application/json', ...authHeaders() },
113→        body: JSON.stringify({ sessionId, timeoutSeconds }),
114→      });
115→      const data = await parseJson<SandboxSessionResponse>(res);
116→      return { status: res.status, data };
117→    },
118→
119→    /** GET /sessions/:id — get session info */
120→    async getSession(
121→      sessionId: string
122→    ): Promise<{ status: number; data: SandboxSessionResponse | SandboxErrorResponse }> {
123→      const res = await fetch(`${normalizedUrl}/sessions/${encodeURIComponent(sessionId)}`, {
124→        headers: authHeaders(),
125→      });
126→      const data = await parseJson<SandboxSessionResponse | SandboxErrorResponse>(res);
127→      return { status: res.status, data };
128→    },
129→
130→    /** DELETE /sessions/:id — destroy a session */
131→    async destroySession(
132→      sessionId: string
133→    ): Promise<{ status: number; data: { sessionId: string; destroyed: boolean } }> {
134→      const res = await fetch(`${normalizedUrl}/sessions/${encodeURIComponent(sessionId)}`, {
135→        method: 'DELETE',
136→        headers: authHeaders(),
137→      });
138→      const data = await parseJson<{ sessionId: string; destroyed: boolean }>(res);
139→      return { status: res.status, data };
140→    },
141→
142→    /** POST /execute-tool — execute a tool within a session */
143→    async executeTool(opts: {
144→      packageName: string;
145→      name: string;
146→      version?: string;
147→      params: Record<string, unknown>;
148→      sessionId?: string;
149→      env?: Record<string, string>;
150→    }): Promise<{ status: number; data: SandboxExecuteResponse }> {
151→      const res = await fetch(`${normalizedUrl}/execute-tool`, {
152→        method: 'POST',
153→        headers: { 'Content-Type': 'application/json', ...authHeaders() },
154→        body: JSON.stringify(opts),
155→      });
156→      const data = await parseJson<SandboxExecuteResponse>(res);
157→      return { status: res.status, data };
158→    },
159→
160→    /** Raw request — for auth testing without auto-injecting token */
161→    async rawRequest(
162→      method: string,
163→      path: string,
164→      opts?: { body?: unknown; headers?: Record<string, string> }
165→    ): Promise<Response> {
166→      const headers: Record<string, string> = { ...opts?.headers };
167→      if (opts?.body !== undefined) {
168→        headers['Content-Type'] = 'application/json';
169→      }
170→      return fetch(`${normalizedUrl}${path}`, {
171→        method,
172→        headers,
173→        body: opts?.body !== undefined ? JSON.stringify(opts.body) : undefined,
174→      });
175→    },
176→  };
177→}
178→
179→export type SandboxClient = ReturnType<typeof createSandboxClient>;
