/**
 * Sandbox Server — Tool execution integration tests
 *
 * Tests POST /execute-tool with shellExec, writeFile, readFile, listFiles.
 */

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import {
  type SandboxTestContext,
  getSandboxTestContext,
  isSandboxAvailable,
} from './_helpers/sandbox-context';

const TOOL_PKG = '@tpmjs/official-sandbox-shell';
const TOOL_VERSION = 'latest';

describe.skipIf(!isSandboxAvailable())('Sandbox Tool Execution', () => {
  let ctx: SandboxTestContext;
  let sessionId: string;

  beforeAll(async () => {
    ctx = getSandboxTestContext();
    sessionId = ctx.uniqueSessionId('tools');
    ctx.trackSession(sessionId);
    await ctx.client.createSession(sessionId);
  });

  afterAll(async () => {
    await ctx.cleanup();
  });

  // ─── shellExec ───────────────────────────────────────────────────────────

  describe('shellExec', () => {
    it('should execute echo and return stdout', async () => {
      const { status, data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'shellExec',
        version: TOOL_VERSION,
        sessionId,
        params: { command: 'echo "hello sandbox"' },
      });

      expect(status).toBe(200);
      expect(data.success).toBe(true);
      const output = data.output as { stdout: string; exitCode: number };
      expect(output.stdout).toContain('hello sandbox');
      expect(output.exitCode).toBe(0);
    });

    it('should return non-zero exit code on failure', async () => {
      const { data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'shellExec',
        version: TOOL_VERSION,
        sessionId,
        params: { command: 'exit 42' },
      });

      expect(data.success).toBe(true);
      const output = data.output as { exitCode: number };
      expect(output.exitCode).toBe(42);
    });

    it('should timeout a long-running command', async () => {
      const { data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'shellExec',
        version: TOOL_VERSION,
        sessionId,
        params: { command: 'sleep 60', timeout: 2000 },
      });

      expect(data.success).toBe(true);
      const output = data.output as { exitCode: number; stderr: string };
      expect(output.exitCode).toBe(137);
      expect(output.stderr).toMatch(/TIMEOUT/i);
    }, 15_000);
  });

  // ─── writeFile + readFile round-trip ─────────────────────────────────────

  describe('writeFile + readFile', () => {
    it('should write and read a file', async () => {
      const content = `Hello from test at ${Date.now()}`;

      // Write
      const writeRes = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'writeFile',
        version: TOOL_VERSION,
        sessionId,
        params: { path: 'test-roundtrip.txt', content },
      });
      expect(writeRes.data.success).toBe(true);
      const writeOut = writeRes.data.output as { success: boolean; bytesWritten: number };
      expect(writeOut.success).toBe(true);
      expect(writeOut.bytesWritten).toBeGreaterThan(0);

      // Read
      const readRes = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'readFile',
        version: TOOL_VERSION,
        sessionId,
        params: { path: 'test-roundtrip.txt' },
      });
      expect(readRes.data.success).toBe(true);
      const readOut = readRes.data.output as { content: string };
      expect(readOut.content).toBe(content);
    });

    it('should create parent directories with createDirs', async () => {
      const writeRes = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'writeFile',
        version: TOOL_VERSION,
        sessionId,
        params: { path: 'deep/nested/dir/file.txt', content: 'nested content', createDirs: true },
      });
      expect(writeRes.data.success).toBe(true);

      const readRes = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'readFile',
        version: TOOL_VERSION,
        sessionId,
        params: { path: 'deep/nested/dir/file.txt' },
      });
      expect(readRes.data.success).toBe(true);
      const readOut = readRes.data.output as { content: string };
      expect(readOut.content).toBe('nested content');
    });
  });

  // ─── listFiles ───────────────────────────────────────────────────────────

  describe('listFiles', () => {
    it('should list files at workspace root', async () => {
      // Ensure at least one file exists
      await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'writeFile',
        version: TOOL_VERSION,
        sessionId,
        params: { path: 'list-test.txt', content: 'x' },
      });

      const { data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'listFiles',
        version: TOOL_VERSION,
        sessionId,
        params: {},
      });

      expect(data.success).toBe(true);
      const output = data.output as { entries: Array<{ name: string; type: string }> };
      const names = output.entries.map((e) => e.name);
      expect(names).toContain('list-test.txt');
    });

    it('should list files recursively', async () => {
      const { data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'listFiles',
        version: TOOL_VERSION,
        sessionId,
        params: { recursive: true },
      });

      expect(data.success).toBe(true);
      const output = data.output as { entries: Array<{ name: string }> };
      const names = output.entries.map((e) => e.name);
      // Should include the nested file from earlier createDirs test
      expect(names.some((n) => n.includes('deep/nested/dir/file.txt'))).toBe(true);
    });
  });
});

/**
 * Sandbox Server — Security integration tests
 *
 * Tests path traversal blocking, symlink escape prevention,
 * and auth enforcement.
 */

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import {
  type SandboxTestContext,
  getSandboxTestContext,
  isSandboxAvailable,
} from './_helpers/sandbox-context';

const TOOL_PKG = '@tpmjs/official-sandbox-shell';
const TOOL_VERSION = 'latest';

describe.skipIf(!isSandboxAvailable())('Sandbox Security', () => {
  let ctx: SandboxTestContext;
  let sessionId: string;

  beforeAll(async () => {
    ctx = getSandboxTestContext();
    sessionId = ctx.uniqueSessionId('security');
    ctx.trackSession(sessionId);
    await ctx.client.createSession(sessionId);
  });

  afterAll(async () => {
    await ctx.cleanup();
  });

  // ─── Path Traversal ──────────────────────────────────────────────────────

  describe('path traversal', () => {
    it('should block readFile with ../../../etc/passwd', async () => {
      const { data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'readFile',
        version: TOOL_VERSION,
        sessionId,
        params: { path: '../../../etc/passwd' },
      });

      expect(data.success).toBe(false);
      expect(data.error).toMatch(/escapes sandbox/i);
    });

    it('should block writeFile with ../../tmp/evil.txt', async () => {
      const { data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'writeFile',
        version: TOOL_VERSION,
        sessionId,
        params: { path: '../../tmp/evil.txt', content: 'pwned' },
      });

      expect(data.success).toBe(false);
      expect(data.error).toMatch(/escapes sandbox/i);
    });
  });

  // ─── Symlink Escape ──────────────────────────────────────────────────────

  describe('symlink escape', () => {
    it('should block readFile through a symlink that escapes the sandbox', async () => {
      // Create a symlink pointing to /etc/hostname
      await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'shellExec',
        version: TOOL_VERSION,
        sessionId,
        params: { command: 'ln -sf /etc/hostname escape-link' },
      });

      // Try to read through the symlink
      const { data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'readFile',
        version: TOOL_VERSION,
        sessionId,
        params: { path: 'escape-link' },
      });

      expect(data.success).toBe(false);
      expect(data.error).toMatch(/escapes sandbox/i);
    });
  });

  // ─── Auth Enforcement ────────────────────────────────────────────────────

  describe('authentication', () => {
    it('should return 401 for POST /sessions without auth header', async () => {
      // Only meaningful when EXECUTOR_API_KEY is set on the server
      const apiKey = process.env.SANDBOX_TEST_API_KEY;
      if (!apiKey) {
        console.log('Skipping: SANDBOX_TEST_API_KEY not set (server has no auth)');
        return;
      }

      const res = await ctx.client.rawRequest('POST', '/sessions', {
        body: { sessionId: 'no-auth-test' },
        // No Authorization header
      });

      expect(res.status).toBe(401);
      const body = await res.json();
      expect(body.error).toMatch(/unauthorized/i);
    });

    it('should allow GET /health without auth', async () => {
      const res = await ctx.client.rawRequest('GET', '/health');
      expect(res.status).toBe(200);
    });

    it('should allow GET /metrics without auth', async () => {
      const res = await ctx.client.rawRequest('GET', '/metrics');
      expect(res.status).toBe(200);
    });
  });
});

/**
 * Sandbox Server — Session isolation & git integration tests
 *
 * Tests that two sessions have separate workspaces,
 * and that git operations work within a session.
 */

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import {
  type SandboxTestContext,
  getSandboxTestContext,
  isSandboxAvailable,
} from './_helpers/sandbox-context';

const TOOL_PKG = '@tpmjs/official-sandbox-shell';
const TOOL_VERSION = 'latest';

describe.skipIf(!isSandboxAvailable())('Sandbox Isolation & Git', () => {
  let ctx: SandboxTestContext;

  beforeAll(() => {
    ctx = getSandboxTestContext();
  });

  afterAll(async () => {
    await ctx.cleanup();
  });

  // ─── Session Isolation ───────────────────────────────────────────────────

  describe('session isolation', () => {
    it('should keep workspaces separate between sessions', async () => {
      const sessionA = ctx.uniqueSessionId('iso-a');
      const sessionB = ctx.uniqueSessionId('iso-b');
      ctx.trackSession(sessionA);
      ctx.trackSession(sessionB);

      await ctx.client.createSession(sessionA);
      await ctx.client.createSession(sessionB);

      // Write a file in session A
      await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'writeFile',
        version: TOOL_VERSION,
        sessionId: sessionA,
        params: { path: 'only-in-a.txt', content: 'session A data' },
      });

      // List files in session B — should NOT contain the file
      const { data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'listFiles',
        version: TOOL_VERSION,
        sessionId: sessionB,
        params: {},
      });

      expect(data.success).toBe(true);
      const output = data.output as { entries: Array<{ name: string }> };
      const names = output.entries.map((e) => e.name);
      expect(names).not.toContain('only-in-a.txt');
    });
  });

  // ─── Git Operations ──────────────────────────────────────────────────────

  describe('git operations', () => {
    let gitSessionId: string;

    beforeAll(async () => {
      gitSessionId = ctx.uniqueSessionId('git');
      ctx.trackSession(gitSessionId);
      await ctx.client.createSession(gitSessionId);
    });

    it('should clone a public repo', async () => {
      const { data } = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'shellExec',
        version: TOOL_VERSION,
        sessionId: gitSessionId,
        params: { command: 'git clone --depth 1 https://github.com/octocat/Hello-World.git' },
      });

      expect(data.success).toBe(true);
      const output = data.output as { exitCode: number };
      expect(output.exitCode).toBe(0);

      // Verify the repo was cloned
      const listRes = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'listFiles',
        version: TOOL_VERSION,
        sessionId: gitSessionId,
        params: { path: 'Hello-World' },
      });

      expect(listRes.data.success).toBe(true);
      const listOutput = listRes.data.output as { entries: Array<{ name: string }> };
      const names = listOutput.entries.map((e) => e.name);
      expect(names).toContain('README');
    }, 90_000);

    it('should init, commit, and verify git log', async () => {
      // Create a new repo
      const cmds = [
        'mkdir my-repo && cd my-repo && git init',
        'cd my-repo && git config user.email "test@tpmjs.com" && git config user.name "Test Bot"',
      ];

      for (const cmd of cmds) {
        const { data } = await ctx.client.executeTool({
          packageName: TOOL_PKG,
          name: 'shellExec',
          version: TOOL_VERSION,
          sessionId: gitSessionId,
          params: { command: cmd },
        });
        expect(data.success).toBe(true);
      }

      // Create a file
      await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'writeFile',
        version: TOOL_VERSION,
        sessionId: gitSessionId,
        params: { path: 'my-repo/hello.txt', content: 'Hello from sandbox test' },
      });

      // Stage and commit
      const commitRes = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'shellExec',
        version: TOOL_VERSION,
        sessionId: gitSessionId,
        params: { command: 'cd my-repo && git add . && git commit -m "initial commit"' },
      });
      expect(commitRes.data.success).toBe(true);
      const commitOut = commitRes.data.output as { exitCode: number };
      expect(commitOut.exitCode).toBe(0);

      // Verify git log
      const logRes = await ctx.client.executeTool({
        packageName: TOOL_PKG,
        name: 'shellExec',
        version: TOOL_VERSION,
        sessionId: gitSessionId,
        params: { command: 'cd my-repo && git log --oneline' },
      });
      expect(logRes.data.success).toBe(true);
      const logOut = logRes.data.output as { stdout: string; exitCode: number };
      expect(logOut.exitCode).toBe(0);
      expect(logOut.stdout).toContain('initial commit');
    });
  });
});

/**
 * Sandbox Server — Disk quota integration tests
 *
 * Tests that the sandbox enforces per-session disk quotas.
 * Requires the sandbox to be started with SESSION_DISK_QUOTA_MB=5 (or similar small value).
 */

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import {
  type SandboxTestContext,
  getSandboxDiskQuotaMB,
  getSandboxTestContext,
  isSandboxAvailable,
} from './_helpers/sandbox-context';

const TOOL_PKG = '@tpmjs/official-sandbox-shell';
const TOOL_VERSION = 'latest';

describe.skipIf(!isSandboxAvailable())('Sandbox Disk Quota', () => {
  let ctx: SandboxTestContext;
  let sessionId: string;
  const quotaMB = getSandboxDiskQuotaMB();

  beforeAll(async () => {
    ctx = getSandboxTestContext();
    sessionId = ctx.uniqueSessionId('quota');
    ctx.trackSession(sessionId);
    await ctx.client.createSession(sessionId);
  });

  afterAll(async () => {
    await ctx.cleanup();
  });

  it('should reject tool calls after workspace exceeds disk quota', async () => {
    // Skip if quota is unreasonably large (test assumes small quota like 5MB)
    if (quotaMB > 50) {
      console.log(
        `Skipping: SANDBOX_TEST_DISK_QUOTA_MB=${quotaMB} is too large for quota test (need ≤50MB)`
      );
      return;
    }

    // Fill workspace beyond quota using dd
    const fillMB = quotaMB + 2; // exceed by 2MB
    const fillRes = await ctx.client.executeTool({
      packageName: TOOL_PKG,
      name: 'shellExec',
      version: TOOL_VERSION,
      sessionId,
      params: {
        command: `dd if=/dev/zero of=bigfile.bin bs=1M count=${fillMB} 2>/dev/null; echo "done"`,
      },
    });

    expect(fillRes.data.success).toBe(true);

    // Next tool call should be rejected due to quota
    const { status, data } = await ctx.client.executeTool({
      packageName: TOOL_PKG,
      name: 'shellExec',
      version: TOOL_VERSION,
      sessionId,
      params: { command: 'echo "should fail"' },
    });

    expect(status).toBe(413);
    expect(data.success).toBe(false);
    expect(data.error).toMatch(/disk quota exceeded/i);
  }, 30_000);
});

