310→/**
311→ * Execute a tool using a sandbox executor (includes sessionId in request)
312→ */
313→async function executeWithSandbox(
314→  url: string,
315→  apiKey: string | undefined,
316→  request: ExecuteToolRequest,
317→  sessionId: string,
318→  timeout: number = DEFAULT_TIMEOUT
319→): Promise<ExecuteToolResponse> {
320→  const startTime = Date.now();
321→
322→  const headers: Record<string, string> = {
323→    'Content-Type': 'application/json',
324→  };
325→
326→  if (apiKey) {
327→    headers.Authorization = `Bearer ${apiKey}`;
328→  }
329→
330→  // Retry on transient failures (network errors, 429, 502, 503)
331→  let lastError: unknown;
332→  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
333→    try {
334→      const controller = new AbortController();
335→      const timeoutId = setTimeout(() => controller.abort(), timeout);
336→
337→      const response = await fetch(`${url}/execute-tool`, {
338→        method: 'POST',
339→        headers,
340→        body: JSON.stringify({ ...request, sessionId }),
341→        signal: controller.signal,
342→      });
343→
344→      clearTimeout(timeoutId);
345→
346→      const executionTimeMs = Date.now() - startTime;
347→
348→      // Retry on 429 (capacity) or 502/503 (transient server issues)
349→      if (
350→        (response.status === 429 || response.status === 502 || response.status === 503) &&
351→        attempt < MAX_RETRIES
352→      ) {
353→        const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
354→        console.warn(
355→          `[Sandbox] Got ${response.status}, retrying in ${delay}ms (attempt ${attempt + 1})`
356→        );
357→        await new Promise((resolve) => setTimeout(resolve, delay));
358→        continue;
359→      }
360→
361→      if (!response.ok) {
362→        const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
363→          error?: string;
364→        };
365→        return {
366→          success: false,
367→          error: errorData.error || `Sandbox executor error: ${response.status}`,
368→          executionTimeMs,
369→        };
370→      }
371→
372→      const result = (await response.json()) as ExecuteToolResponse;
373→
374→      return {
375→        success: result.success,
376→        output: result.output,
377→        error: result.error,
378→        executionTimeMs: result.executionTimeMs || executionTimeMs,
379→      };
380→    } catch (error) {
381→      lastError = error;
382→
383→      if (error instanceof Error && error.name === 'AbortError') {
384→        return {
385→          success: false,
386→          error: 'Execution timeout',
387→          executionTimeMs: Date.now() - startTime,
388→        };
389→      }
390→
391→      // Retry on network errors
392→      if (attempt < MAX_RETRIES) {
393→        const msg = error instanceof Error ? error.message : String(error);
394→        if (
395→          msg.includes('ECONNREFUSED') ||
396→          msg.includes('fetch failed') ||
397→          msg.includes('ECONNRESET')
398→        ) {
399→          const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
400→          console.warn(
401→            `[Sandbox] Network error, retrying in ${delay}ms (attempt ${attempt + 1}):`,
402→            msg
403→          );
404→          await new Promise((resolve) => setTimeout(resolve, delay));
405→          continue;
406→        }
407→      }
408→
409→      return {
410→        success: false,
411→        error: error instanceof Error ? error.message : String(error),
412→        executionTimeMs: Date.now() - startTime,
413→      };
414→    }
415→  }
416→
417→  return {
418→    success: false,
419→    error: lastError instanceof Error ? lastError.message : String(lastError),
420→    executionTimeMs: Date.now() - startTime,
421→  };
422→}
