853→ */
854→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
855→  const { username, agentSlug, conversationId } = await context.params;
856→
857→  try {
858→    // Fetch agent by username and slug (include executor fields for sandbox cleanup)
859→    const agent = await prisma.agent.findFirst({
860→      where: {
861→        uid: agentSlug,
862→        user: { username },
863→      },
864→      select: { id: true, executorType: true, executorConfig: true },
865→    });
866→
