async function destroySession(sessionId: string): Promise<boolean> {
  const session = sessions.get(sessionId);
  if (!session) {
    return false;
  }

  sessions.delete(sessionId);

  // Clean up workspace directory
  try {
    await Deno.remove(session.workDir, { recursive: true });
