424→/**
425→ * Execute a tool using the resolved executor configuration
426→ *
427→ * @param config - Resolved executor config (or null for default)
428→ * @param request - Tool execution request
429→ * @param sessionId - Optional session ID for sandbox executors
430→ * @returns Execution result
431→ */
432→export async function executeWithExecutor(
433→  config: ExecutorConfig | null,
434→  request: ExecuteToolRequest,
435→  sessionId?: string
436→): Promise<ExecuteToolResponse> {
437→  const resolvedConfig = config ?? { type: 'default' };
438→
439→  // Use custom URL executor
440→  if (resolvedConfig.type === 'custom_url' && resolvedConfig.url) {
441→    return executeWithCustomUrl(resolvedConfig.url, resolvedConfig.apiKey, request);
442→  }
443→
444→  // Use sandbox executor
445→  if (resolvedConfig.type === 'sandbox' && sessionId) {
446→    const sandboxUrl = resolveSandboxUrl(resolvedConfig);
447→    if (!sandboxUrl) {
448→      return {
449→        success: false,
450→        error:
451→          'Sandbox executor URL not configured. Set AGENT_SANDBOX_URL or provide a custom URL.',
452→        executionTimeMs: 0,
453→      };
454→    }
455→    return executeWithSandbox(sandboxUrl, resolvedConfig.apiKey, request, sessionId);
456→  }
457→
458→  // Default: use existing package-executor (which uses SANDBOX_EXECUTOR_URL)
459→  const result = await executePackage(request.packageName, request.name, request.params, {
460→    env: request.env,
461→    version: request.version,
462→  });
463→
464→  return {
465→    success: result.success,
466→    output: result.output,
467→    error: result.error,
468→    executionTimeMs: result.executionTimeMs,
469→  };
470→}
