476→ * @param apiKey - Optional API key for authentication
477→ * @returns Health check response or error
478→ */
479→export async function checkExecutorHealth(
480→  url: string,
481→  apiKey?: string
482→): Promise<{ healthy: boolean; response?: ExecutorHealthResponse; error?: string }> {
483→  const headers: Record<string, string> = {};
484→
485→  if (apiKey) {
486→    headers.Authorization = `Bearer ${apiKey}`;
487→  }
488→
489→  try {
