615→/**
616→ * Get executor description for display
617→ */
618→export function getExecutorDescription(config: ExecutorConfig | null): string {
619→  if (!config || config.type === 'default') {
620→    return 'TPMJS Default Executor';
621→  }
622→
623→  if (config.type === 'custom_url') {
624→    try {
625→      const url = new URL(config.url);
626→      return `Custom: ${url.hostname}`;
627→    } catch {
628→      return 'Custom Executor';
629→    }
630→  }
631→
632→  if (config.type === 'sandbox') {
633→    if (config.url) {
634→      try {
635→        const url = new URL(config.url);
636→        return `Sandbox: ${url.hostname}`;
637→      } catch {
638→        return 'Agent Sandbox';
639→      }
640→    }
641→    return 'TPMJS Agent Sandbox';
642→  }
643→
644→  return 'Unknown Executor';
645→}
