 24→/**
 25→ * GET /api/agents
 26→ * List all agents owned by the authenticated user
 27→ */
 28→export async function GET(request: NextRequest): Promise<NextResponse> {
 29→  try {
 30→    const authResult = await authenticateRequest();
 31→    if (!authResult.authenticated || !authResult.userId) {
 32→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 33→    }
 34→
 35→    const { searchParams } = new URL(request.url);
 36→    const limit = Math.min(Number.parseInt(searchParams.get('limit') || '20', 10), 50);
 37→    const offset = Number.parseInt(searchParams.get('offset') || '0', 10);
 38→
 39→    const agents = await prisma.agent.findMany({
 40→      where: { userId: authResult.userId },
 41→      select: {
 42→        id: true,
 43→        uid: true,
 44→        name: true,
 45→        description: true,
 46→        provider: true,
 47→        modelId: true,
 48→        temperature: true,
 49→        maxToolCallsPerTurn: true,
 50→        maxMessagesInContext: true,
 51→        isPublic: true,
 52→        createdAt: true,
 53→        updatedAt: true,
 54→        _count: {
 55→          select: {
 56→            tools: true,
 57→            collections: true,
 58→          },
 59→        },
 60→      },
 61→      orderBy: { updatedAt: 'desc' },
 62→      take: limit + 1,
 63→      skip: offset,
 64→    });
 65→
 66→    const hasMore = agents.length > limit;
 67→    const data = hasMore ? agents.slice(0, limit) : agents;
 68→
 69→    return NextResponse.json({
 70→      success: true,
 71→      data: data.map((a) => ({
 72→        ...a,
 73→        toolCount: a._count.tools,
 74→        collectionCount: a._count.collections,
 75→        _count: undefined,
 76→      })),
 77→      pagination: {
 78→        limit,
 79→        offset,
 80→        count: data.length,
 81→        hasMore,
 82→      },
 83→    });
 84→  } catch (error) {
 85→    console.error('Failed to list agents:', error);
 86→    return NextResponse.json({ success: false, error: 'Failed to list agents' }, { status: 500 });
 87→  }
 88→}
