 11→// Agent type includes executor config fields from Prisma schema
 12→type AgentWithRelations = Agent & {
 13→  collections: (AgentCollection & {
 14→    collection: Collection & {
 15→      tools: Array<{
 16→        tool: Tool & { package: Package };
 17→      }>;
 18→    };
 19→  })[];
 20→  tools: (AgentTool & {
 21→    tool: Tool & { package: Package };
 22→  })[];
 23→};
 24→
 25→/**
 26→ * Fetch a full agent with all tool relations
 27→ * Includes executor config for cascade resolution
 28→ */
 29→export async function fetchAgentWithTools(agentId: string): Promise<AgentWithRelations | null> {
 30→  return prisma.agent.findUnique({
 31→    where: { id: agentId },
 32→    include: {
 33→      collections: {
 34→        include: {
 35→          collection: {
 36→            include: {
 37→              tools: {
 38→                include: {
 39→                  tool: {
 40→                    include: { package: true },
 41→                  },
 42→                },
 43→                orderBy: { position: 'asc' },
 44→              },
 45→            },
 46→          },
 47→        },
 48→        orderBy: { position: 'asc' },
 49→      },
 50→      tools: {
 51→        include: {
 52→          tool: {
 53→            include: { package: true },
 54→          },
 55→        },
 56→        orderBy: { position: 'asc' },
 57→      },
 58→    },
 59→  });
 60→}
