241→/**
242→ * DELETE /api/agents/[id]
243→ * Delete an agent and all its conversations
244→ */
245→export async function DELETE(_request: NextRequest, context: RouteContext) {
246→  const requestId = crypto.randomUUID();
247→
248→  try {
249→    const authResult = await authenticateRequest();
250→    if (!authResult.authenticated || !authResult.userId) {
251→      return apiUnauthorized('Authentication required', requestId);
252→    }
253→
254→    const { id } = await context.params;
255→
256→    // Check ownership and get name for activity log
257→    const existing = await prisma.agent.findUnique({
258→      where: { id },
259→      select: { userId: true, name: true },
260→    });
261→    if (!existing) {
262→      return apiNotFound('Agent', requestId);
263→    }
264→    if (existing.userId !== authResult.userId) {
265→      return apiForbidden('Access denied', requestId);
266→    }
267→
268→    await prisma.agent.delete({ where: { id } });
269→
270→    // Log activity (fire-and-forget) - note: agentId is not included since agent is deleted
271→    logActivity({
272→      userId: authResult.userId,
273→      type: 'AGENT_DELETED',
274→      targetName: existing.name,
275→      targetType: 'agent',
276→    });
277→
278→    return apiSuccess({ deleted: true }, { requestId });
279→  } catch (error) {
280→    console.error('Failed to delete agent:', error);
281→    return apiInternalError('Failed to delete agent', requestId);
282→  }
283→}
