  1→import { prisma } from '@tpmjs/db';
  2→import { AddCollectionToAgentSchema, AGENT_LIMITS } from '@tpmjs/types/agent';
  3→import { headers } from 'next/headers';
  4→import { type NextRequest, NextResponse } from 'next/server';
  5→
  6→import { logActivity } from '~/lib/activity';
  7→import { auth } from '~/lib/auth';
  8→
  9→export const runtime = 'nodejs';
 10→export const dynamic = 'force-dynamic';
 11→
 12→type RouteContext = {
 13→  params: Promise<{ id: string }>;
 14→};
 15→
 16→/**
 17→ * GET /api/agents/[id]/collections
 18→ * List collections attached to an agent
 19→ */
 20→export async function GET(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
 21→  try {
 22→    const session = await auth.api.getSession({ headers: await headers() });
 23→    const { id } = await context.params;
 24→
 25→    const agent = await prisma.agent.findUnique({
 26→      where: { id },
 27→      select: { userId: true, isPublic: true },
 28→    });
 29→
 30→    if (!agent) {
 31→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
 32→    }
 33→
 34→    const isOwner = session?.user?.id === agent.userId;
 35→    if (!isOwner && !agent.isPublic) {
 36→      return NextResponse.json({ success: false, error: 'Access denied' }, { status: 403 });
 37→    }
 38→
 39→    const collections = await prisma.agentCollection.findMany({
 40→      where: { agentId: id },
 41→      include: {
 42→        collection: {
 43→          select: {
 44→            id: true,
 45→            name: true,
 46→            description: true,
 47→            _count: { select: { tools: true } },
 48→          },
 49→        },
 50→      },
 51→      orderBy: { position: 'asc' },
 52→    });
 53→
 54→    return NextResponse.json({
 55→      success: true,
 56→      data: collections.map((ac) => ({
 57→        id: ac.id,
 58→        collectionId: ac.collectionId,
 59→        position: ac.position,
 60→        addedAt: ac.addedAt,
 61→        collection: {
 62→          id: ac.collection.id,
