 78→/**
 79→ * POST /api/agents/[id]/collections
 80→ * Add a collection to an agent
 81→ */
 82→export async function POST(request: NextRequest, context: RouteContext): Promise<NextResponse> {
 83→  try {
 84→    const session = await auth.api.getSession({ headers: await headers() });
 85→    if (!session?.user?.id) {
 86→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 87→    }
 88→
 89→    const { id } = await context.params;
 90→    const body = await request.json();
 91→    const parsed = AddCollectionToAgentSchema.safeParse(body);
 92→    if (!parsed.success) {
 93→      return NextResponse.json(
 94→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
 95→        { status: 400 }
 96→      );
 97→    }
 98→
 99→    // Check agent ownership
100→    const agent = await prisma.agent.findUnique({
101→      where: { id },
102→      select: { userId: true, name: true, _count: { select: { collections: true } } },
103→    });
104→    if (!agent) {
105→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
106→    }
107→    if (agent.userId !== session.user.id) {
108→      return NextResponse.json({ success: false, error: 'Access denied' }, { status: 403 });
109→    }
110→
111→    // Check collection limit
112→    if (agent._count.collections >= AGENT_LIMITS.MAX_COLLECTIONS_PER_AGENT) {
113→      return NextResponse.json(
114→        {
115→          success: false,
116→          error: `Maximum ${AGENT_LIMITS.MAX_COLLECTIONS_PER_AGENT} collections per agent`,
117→        },
118→        { status: 400 }
119→      );
120→    }
121→
122→    // Check collection exists and user has access
123→    const collection = await prisma.collection.findUnique({
124→      where: { id: parsed.data.collectionId },
125→      select: {
126→        id: true,
127→        name: true,
128→        userId: true,
129→        isPublic: true,
130→        _count: { select: { tools: true } },
131→      },
132→    });
133→    if (!collection) {
134→      return NextResponse.json({ success: false, error: 'Collection not found' }, { status: 404 });
135→    }
136→    if (collection.userId !== session.user.id && !collection.isPublic) {
137→      return NextResponse.json(
138→        { success: false, error: 'Collection access denied' },
139→        { status: 403 }
140→      );
141→    }
142→
143→    // Check if already added
144→    const existing = await prisma.agentCollection.findUnique({
145→      where: {
146→        agentId_collectionId: { agentId: id, collectionId: parsed.data.collectionId },
147→      },
148→    });
149→    if (existing) {
150→      return NextResponse.json(
151→        { success: false, error: 'Collection already added to agent' },
152→        { status: 409 }
153→      );
154→    }
155→
156→    // Get next position
157→    const maxPosition = await prisma.agentCollection.aggregate({
158→      where: { agentId: id },
159→      _max: { position: true },
160→    });
161→    const position = parsed.data.position ?? (maxPosition._max.position ?? -1) + 1;
162→
163→    const agentCollection = await prisma.agentCollection.create({
164→      data: {
165→        agentId: id,
166→        collectionId: parsed.data.collectionId,
167→        position,
168→      },
169→      include: {
170→        collection: {
171→          select: {
172→            id: true,
173→            name: true,
174→            _count: { select: { tools: true } },
175→          },
176→        },
177→      },
178→    });
179→
180→    // Log activity (fire-and-forget)
181→    logActivity({
182→      userId: session.user.id,
183→      type: 'AGENT_COLLECTION_ADDED',
184→      targetName: agent.name,
185→      targetType: 'agent',
186→      agentId: id,
187→      collectionId: agentCollection.collectionId,
188→      metadata: { collectionName: agentCollection.collection.name },
189→    });
190→
191→    return NextResponse.json(
192→      {
193→        success: true,
194→        data: {
195→          id: agentCollection.id,
196→          collectionId: agentCollection.collectionId,
197→          position: agentCollection.position,
198→          addedAt: agentCollection.addedAt,
199→          collection: {
200→            ...agentCollection.collection,
201→            toolCount: agentCollection.collection._count.tools,
202→          },
203→        },
204→      },
205→      { status: 201 }
206→    );
207→  } catch (error) {
208→    console.error('Failed to add collection to agent:', error);
209→    return NextResponse.json(
210→      { success: false, error: 'Failed to add collection' },
211→      { status: 500 }
212→    );
213→  }
214→}
