 12→interface ExecutorConfigPanelProps {
 13→  value: ExecutorConfig | null;
 14→  onChange: (config: ExecutorConfig | null) => void;
 15→  disabled?: boolean;
 16→}
 17→
 18→interface VerificationResult {
 19→  valid: boolean;
 20→  healthCheck?: {
 21→    healthy: boolean;
 22→    response?: { status: string; version?: string };
 23→  };
 24→  testExecution?: {
 25→    success: boolean;
 26→    executionTimeMs: number;
 27→  };
 28→  errors: string[];
 29→}
 30→
 31→type ExecutorTypeOption = 'default' | 'custom_url' | 'sandbox';
 32→
 33→function getInitialType(value: ExecutorConfig | null): ExecutorTypeOption {
 34→  if (value?.type === 'custom_url') return 'custom_url';
 35→  if (value?.type === 'sandbox') return 'sandbox';
 36→  return 'default';
 37→}
 38→
 39→function getInitialUrl(value: ExecutorConfig | null): string {
 40→  if (value?.type === 'custom_url') return value.url;
 41→  if (value?.type === 'sandbox') return value.url ?? '';
 42→  return '';
 43→}
 44→
 45→function getInitialApiKey(value: ExecutorConfig | null): string {
 46→  if (value?.type === 'custom_url') return value.apiKey ?? '';
 47→  if (value?.type === 'sandbox') return value.apiKey ?? '';
 48→  return '';
 49→}
 50→
 51→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Component has multiple states for executor configuration
 52→export function ExecutorConfigPanel({
 53→  value,
 54→  onChange,
 55→  disabled = false,
 56→}: ExecutorConfigPanelProps): React.ReactElement {
 57→  const [executorType, setExecutorType] = useState<ExecutorTypeOption>(getInitialType(value));
 58→  const [customUrl, setCustomUrl] = useState(getInitialUrl(value));
 59→  const [apiKey, setApiKey] = useState(getInitialApiKey(value));
 60→  const [isVerifying, setIsVerifying] = useState(false);
 61→  const [verificationResult, setVerificationResult] = useState<VerificationResult | null>(null);
 62→  const [urlError, setUrlError] = useState<string | null>(null);
 63→
 64→  const handleTypeChange = (type: ExecutorTypeOption) => {
 65→    setExecutorType(type);
 66→    setVerificationResult(null);
 67→    setUrlError(null);
 68→
 69→    if (type === 'default') {
 70→      onChange({ type: 'default' });
 71→    } else if (type === 'custom_url') {
 72→      if (customUrl) {
 73→        onChange({
 74→          type: 'custom_url',
 75→          url: customUrl,
 76→          apiKey: apiKey || undefined,
 77→        });
 78→      }
 79→    } else if (type === 'sandbox') {
 80→      onChange({
 81→        type: 'sandbox',
 82→        url: customUrl || undefined,
 83→        apiKey: apiKey || undefined,
 84→      });
 85→    }
 86→  };
 87→
 88→  const handleUrlChange = (url: string) => {
 89→    setCustomUrl(url);
 90→    setVerificationResult(null);
 91→    setUrlError(null);
 92→
 93→    if (executorType === 'custom_url' && url) {
 94→      onChange({
 95→        type: 'custom_url',
