366→            >
367→              <div className="flex items-center gap-2">
368→                <Icon
369→                  icon={verificationResult.valid ? 'check' : 'x'}
370→                  className={`w-4 h-4 ${
371→                    verificationResult.valid ? 'text-green-500' : 'text-red-500'
372→                  }`}
373→                />
374→                <span
375→                  className={`font-medium ${
376→                    verificationResult.valid ? 'text-green-500' : 'text-red-500'
377→                  }`}
