  1→'use client';
  2→
  3→import { Button } from '@tpmjs/ui/Button/Button';
  4→import { Icon } from '@tpmjs/ui/Icon/Icon';
  5→import { Input } from '@tpmjs/ui/Input/Input';
  6→import { Textarea } from '@tpmjs/ui/Textarea/Textarea';
  7→import { useCallback, useMemo, useRef, useState } from 'react';
  8→import { parseEnvString } from '~/lib/utils/env-parser';
  9→
 10→interface EnvVar {
 11→  key: string;
 12→  value: string;
 13→}
 14→
 15→export interface EnvVarsEditorProps {
 16→  /** Current env vars as Record<string, string> */
 17→  value: Record<string, string> | null | undefined;
 18→  /** Called when env vars change */
 19→  onChange: (value: Record<string, string> | null) => void;
 20→  /** Title shown above the editor */
 21→  title?: string;
 22→  /** Description shown below the title */
 23→  description?: string;
 24→  /** Placeholder for new key input */
 25→  keyPlaceholder?: string;
 26→  /** Placeholder for new value input */
 27→  valuePlaceholder?: string;
 28→  /** Whether the editor is disabled */
 29→  disabled?: boolean;
 30→  /** Show the paste .env snippet feature */
 31→  showPasteEnv?: boolean;
 32→  /** className for the container */
 33→  className?: string;
 34→}
 35→
 36→/**
 37→ * Reusable component for editing environment variables
 38→ * Used for agent env vars, collection env vars, API keys, and user-level env vars
 39→ */
 40→export function EnvVarsEditor({
 41→  value,
 42→  onChange,
 43→  title = 'Environment Variables',
 44→  description,
 45→  keyPlaceholder = 'NEW_KEY',
 46→  valuePlaceholder = 'value',
 47→  disabled = false,
 48→  showPasteEnv = true,
 49→  className = '',
 50→}: EnvVarsEditorProps) {
 51→  // Internal array state for editing
 52→  const [envVars, setEnvVars] = useState<EnvVar[]>([]);
 53→  const [newEnvKey, setNewEnvKey] = useState('');
 54→  const [newEnvValue, setNewEnvValue] = useState('');
 55→  const [showPasteModal, setShowPasteModal] = useState(false);
 56→  const [pasteContent, setPasteContent] = useState('');
 57→
 58→  // Sync from prop to internal state (only when value actually changes)
 59→  // Using a ref to track the serialized value to prevent unnecessary state updates
 60→  const valueRef = useRef<string | null>(null);
 61→  const serializedValue = value ? JSON.stringify(value) : null;
 62→
 63→  if (serializedValue !== valueRef.current) {
 64→    valueRef.current = serializedValue;
 65→    const newEnvVars =
 66→      value && typeof value === 'object'
 67→        ? Object.entries(value).map(([key, val]) => ({ key, value: val }))
 68→        : [];
 69→    // Only update if the arrays are actually different
 70→    if (JSON.stringify(newEnvVars) !== JSON.stringify(envVars)) {
 71→      setEnvVars(newEnvVars);
 72→    }
 73→  }
 74→
 75→  // Convert array to record and call onChange
 76→  const emitChange = useCallback(
 77→    (vars: EnvVar[]) => {
 78→      const record: Record<string, string> = {};
 79→      for (const { key, value: val } of vars) {
 80→        const trimmedKey = key.trim();
 81→        if (trimmedKey) {
 82→          record[trimmedKey] = val;
 83→        }
 84→      }
 85→      onChange(Object.keys(record).length > 0 ? record : null);
 86→    },
 87→    [onChange]
 88→  );
 89→
 90→  // Update a single env var
 91→  const updateEnvVar = useCallback(
 92→    (index: number, field: 'key' | 'value', newValue: string) => {
 93→      const updated = [...envVars];
 94→      const current = updated[index];
 95→      if (!current) return;
 96→      updated[index] = {
 97→        key: field === 'key' ? newValue.toUpperCase() : current.key,
 98→        value: field === 'value' ? newValue : current.value,
 99→      };
100→      setEnvVars(updated);
101→      emitChange(updated);
102→    },
103→    [envVars, emitChange]
104→  );
105→
106→  // Remove an env var
107→  const removeEnvVar = useCallback(
108→    (index: number) => {
109→      const updated = envVars.filter((_, i) => i !== index);
110→      setEnvVars(updated);
111→      emitChange(updated);
112→    },
113→    [envVars, emitChange]
114→  );
115→
116→  // Add a new env var
117→  const addEnvVar = useCallback(() => {
118→    if (!newEnvKey.trim()) return;
119→
120→    const updated = [...envVars, { key: newEnvKey.trim().toUpperCase(), value: newEnvValue }];
121→    setEnvVars(updated);
122→    emitChange(updated);
123→    setNewEnvKey('');
124→    setNewEnvValue('');
125→  }, [envVars, newEnvKey, newEnvValue, emitChange]);
126→
127→  // Handle pasting .env content
128→  const handlePasteEnv = useCallback(() => {
129→    const parsed = parseEnvString(pasteContent);
130→    if (parsed.length === 0) {
131→      return;
132→    }
133→
134→    // Merge with existing, new values override existing keys
135→    const existingMap = new Map(envVars.map((e) => [e.key, e.value]));
136→    for (const { key, value: val } of parsed) {
137→      existingMap.set(key, val);
138→    }
139→
140→    const updated = Array.from(existingMap.entries()).map(([key, val]) => ({ key, value: val }));
141→    setEnvVars(updated);
142→    emitChange(updated);
143→    setPasteContent('');
144→    setShowPasteModal(false);
145→  }, [pasteContent, envVars, emitChange]);
146→
147→  // Preview of parsed env vars
148→  const parsedPreview = useMemo(() => {
149→    if (!pasteContent.trim()) return [];
150→    return parseEnvString(pasteContent);
151→  }, [pasteContent]);
152→
153→  return (
154→    <div className={className}>
155→      {/* Header */}
156→      <div className="flex items-center justify-between mb-3">
157→        <div>
158→          <h3 className="text-sm font-medium text-foreground">{title}</h3>
159→          {description && <p className="text-xs text-foreground-tertiary mt-0.5">{description}</p>}
160→        </div>
161→        {showPasteEnv && (
162→          <Button
163→            size="sm"
164→            variant="ghost"
165→            onClick={() => setShowPasteModal(!showPasteModal)}
166→            disabled={disabled}
167→            title="Paste .env snippet"
168→          >
169→            <Icon icon="copy" size="xs" className="mr-1" />
170→            Paste .env
171→          </Button>
172→        )}
173→      </div>
174→
175→      {/* Paste .env modal/section */}
176→      {showPasteModal && (
177→        <div className="mb-4 p-3 bg-surface-secondary rounded-lg border border-border">
178→          <div className="flex items-center justify-between mb-2">
179→            <span className="text-xs font-medium text-foreground">Paste .env snippet</span>
180→            <Button size="sm" variant="ghost" onClick={() => setShowPasteModal(false)}>
181→              <Icon icon="x" size="xs" />
182→            </Button>
183→          </div>
184→          <Textarea
185→            value={pasteContent}
186→            onChange={(e) => setPasteContent(e.target.value)}
187→            placeholder={`# Paste your .env content here\nAPI_KEY=your-api-key\nDATABASE_URL="postgres://..."\n`}
188→            className="h-32 text-xs"
189→            resize="none"
190→            disabled={disabled}
191→          />
192→          {parsedPreview.length > 0 && (
193→            <div className="mt-2 text-xs text-foreground-secondary">
194→              <span className="font-medium">Preview:</span> {parsedPreview.length} variable
195→              {parsedPreview.length !== 1 ? 's' : ''} found
196→              <span className="text-foreground-tertiary ml-1">
197→                ({parsedPreview.map((e) => e.key).join(', ')})
198→              </span>
199→            </div>
200→          )}
201→          <div className="flex justify-end mt-2">
202→            <Button
203→              size="sm"
204→              variant="default"
205→              onClick={handlePasteEnv}
206→              disabled={parsedPreview.length === 0}
207→            >
208→              <Icon icon="plus" size="xs" className="mr-1" />
209→              Add {parsedPreview.length} Variable{parsedPreview.length !== 1 ? 's' : ''}
210→            </Button>
211→          </div>
212→        </div>
213→      )}
214→
215→      {/* Existing env vars */}
216→      {envVars.length > 0 && (
217→        <div className="space-y-2 mb-3">
218→          {envVars.map((env, index) => (
219→            <div key={`env-${env.key || index}`} className="flex items-center gap-2">
220→              <Input
221→                type="text"
222→                value={env.key}
223→                onChange={(e) => updateEnvVar(index, 'key', e.target.value)}
224→                placeholder="KEY"
225→                size="sm"
226→                disabled={disabled}
227→              />
228→              <Input
229→                type="password"
230→                value={env.value}
231→                onChange={(e) => updateEnvVar(index, 'value', e.target.value)}
232→                placeholder="value"
233→                size="sm"
234→                disabled={disabled}
235→              />
236→              <Button
237→                size="sm"
238→                variant="ghost"
239→                onClick={() => removeEnvVar(index)}
240→                title="Remove"
241→                disabled={disabled}
242→              >
243→                <Icon icon="trash" size="xs" />
244→              </Button>
245→            </div>
246→          ))}
247→        </div>
248→      )}
249→
250→      {/* Add new env var */}
251→      <div className="flex items-center gap-2">
252→        <Input
253→          type="text"
254→          value={newEnvKey}
255→          onChange={(e) => setNewEnvKey(e.target.value.toUpperCase())}
256→          placeholder={keyPlaceholder}
257→          size="sm"
258→          disabled={disabled}
259→          onKeyDown={(e) => {
260→            if (e.key === 'Enter' && newEnvKey.trim()) {
261→              addEnvVar();
262→            }
263→          }}
264→        />
265→        <Input
266→          type="text"
267→          value={newEnvValue}
268→          onChange={(e) => setNewEnvValue(e.target.value)}
269→          placeholder={valuePlaceholder}
270→          size="sm"
271→          disabled={disabled}
272→          onKeyDown={(e) => {
273→            if (e.key === 'Enter' && newEnvKey.trim()) {
274→              addEnvVar();
275→            }
276→          }}
277→        />
278→        <Button
279→          size="sm"
280→          variant="secondary"
281→          onClick={addEnvVar}
282→          disabled={disabled || !newEnvKey.trim()}
283→        >
284→          <Icon icon="plus" size="xs" className="mr-1" />
285→          Add
286→        </Button>
287→      </div>
288→    </div>
289→  );
290→}
