 1→import { prisma } from '@tpmjs/db';
 2→import { headers } from 'next/headers';
 3→import { type NextRequest, NextResponse } from 'next/server';
 4→
 5→import { logActivity } from '~/lib/activity';
 6→import { auth } from '~/lib/auth';
 7→
 8→export const runtime = 'nodejs';
 9→export const dynamic = 'force-dynamic';
10→
11→type RouteContext = {
12→  params: Promise<{ id: string; toolId: string }>;
13→};
14→
15→/**
16→ * DELETE /api/agents/[id]/tools/[toolId]
17→ * Remove an individual tool from an agent
18→ */
19→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
20→  try {
21→    const session = await auth.api.getSession({ headers: await headers() });
22→    if (!session?.user?.id) {
23→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
24→    }
25→
26→    const { id, toolId } = await context.params;
27→
28→    // Check agent ownership and get agent name for activity log
29→    const agent = await prisma.agent.findUnique({
30→      where: { id },
31→      select: { userId: true, name: true },
32→    });
33→    if (!agent) {
34→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
35→    }
36→    if (agent.userId !== session.user.id) {
37→      return NextResponse.json({ success: false, error: 'Access denied' }, { status: 403 });
38→    }
39→
40→    // Get tool name for activity log
41→    const tool = await prisma.tool.findUnique({
42→      where: { id: toolId },
43→      select: { name: true },
44→    });
45→
46→    // Delete the agent-tool link
47→    await prisma.agentTool.deleteMany({
48→      where: { agentId: id, toolId },
49→    });
50→
51→    // Log activity (fire-and-forget)
52→    logActivity({
53→      userId: session.user.id,
54→      type: 'AGENT_TOOL_REMOVED',
55→      targetName: agent.name,
56→      targetType: 'agent',
57→      agentId: id,
58→      toolId,
59→      metadata: tool ? { toolName: tool.name } : undefined,
60→    });
61→
62→    return NextResponse.json({
63→      success: true,
64→      data: { removed: true },
65→    });
66→  } catch (error) {
67→    console.error('Failed to remove tool from agent:', error);
68→    return NextResponse.json({ success: false, error: 'Failed to remove tool' }, { status: 500 });
69→  }
70→}
