  1→/**
  2→ * Build AI SDK tools from an agent's collections and individual tools
  3→ */
  4→
  5→import type { Agent, AgentCollection, AgentTool, Collection, Package, Tool } from '@tpmjs/db';
  6→import { prisma } from '@tpmjs/db';
  7→
  8→import { createToolDefinition } from '../ai-agent/tool-executor-agent';
  9→import { parseExecutorConfig, resolveExecutorConfig } from '../executors';
 10→
 11→// Agent type includes executor config fields from Prisma schema
 12→type AgentWithRelations = Agent & {
 13→  collections: (AgentCollection & {
 14→    collection: Collection & {
 15→      tools: Array<{
 16→        tool: Tool & { package: Package };
 17→      }>;
 18→    };
 19→  })[];
 20→  tools: (AgentTool & {
 21→    tool: Tool & { package: Package };
 22→  })[];
 23→};
 24→
 25→/**
 26→ * Fetch a full agent with all tool relations
 27→ * Includes executor config for cascade resolution
 28→ */
 29→export async function fetchAgentWithTools(agentId: string): Promise<AgentWithRelations | null> {
 30→  return prisma.agent.findUnique({
 31→    where: { id: agentId },
 32→    include: {
 33→      collections: {
 34→        include: {
 35→          collection: {
 36→            include: {
 37→              tools: {
 38→                include: {
 39→                  tool: {
 40→                    include: { package: true },
 41→                  },
 42→                },
 43→                orderBy: { position: 'asc' },
 44→              },
 45→            },
 46→          },
 47→        },
 48→        orderBy: { position: 'asc' },
 49→      },
 50→      tools: {
 51→        include: {
 52→          tool: {
 53→            include: { package: true },
 54→          },
 55→        },
 56→        orderBy: { position: 'asc' },
 57→      },
 58→    },
 59→  });
 60→}
 61→
 62→/**
 63→ * Fetch an agent by UID with all tool relations
 64→ * Includes executor config for cascade resolution
 65→ */
 66→export async function fetchAgentByUidWithTools(uid: string): Promise<AgentWithRelations | null> {
 67→  return prisma.agent.findUnique({
 68→    where: { uid },
 69→    include: {
 70→      collections: {
 71→        include: {
 72→          collection: {
 73→            include: {
 74→              tools: {
 75→                include: {
 76→                  tool: {
 77→                    include: { package: true },
 78→                  },
 79→                },
 80→                orderBy: { position: 'asc' },
 81→              },
 82→            },
 83→          },
 84→        },
 85→        orderBy: { position: 'asc' },
 86→      },
 87→      tools: {
 88→        include: {
 89→          tool: {
 90→            include: { package: true },
 91→          },
 92→        },
 93→        orderBy: { position: 'asc' },
 94→      },
 95→    },
 96→  });
 97→}
 98→
 99→/**
100→ * Fetch an agent by ID or UID with all tool relations
101→ * Accepts either the cuid or the user-friendly uid
102→ * Includes executor config for cascade resolution
103→ */
104→export async function fetchAgentByIdOrUidWithTools(
105→  idOrUid: string
106→): Promise<AgentWithRelations | null> {
107→  return prisma.agent.findFirst({
108→    where: {
109→      OR: [{ id: idOrUid }, { uid: idOrUid }],
110→    },
111→    include: {
112→      collections: {
113→        include: {
114→          collection: {
