131→          tool: {
132→            include: { package: true },
133→          },
134→        },
135→        orderBy: { position: 'asc' },
136→      },
137→    },
138→  });
139→}
140→
141→/**
142→ * Fetch an agent by username and uid with all tool relations
143→ * Uses the username/uid pretty URL format
144→ * Includes executor config for cascade resolution
145→ */
146→export async function fetchAgentByUsernameAndUidWithTools(
147→  username: string,
148→  uid: string
149→): Promise<AgentWithRelations | null> {
150→  return prisma.agent.findFirst({
151→    where: {
152→      uid,
153→      user: { username },
154→    },
155→    include: {
156→      collections: {
